create table public.clients(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,phone text,address text,notes text,created_at timestamptz default now());create table public.interventions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,client_name text,title text not null,type text,date date,notes text,created_at timestamptz default now());create table public.stock_items(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,unit text,depot numeric default 0,truck numeric default 0,min_qty numeric default 0,created_at timestamptz default now(),updated_at timestamptz default now());alter table public.clients enable row level security;alter table public.interventions enable row level security;alter table public.stock_items enable row level security;create policy "own clients" on public.clients for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);create policy "own interventions" on public.interventions for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);create policy "own stock" on public.stock_items for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);